def amount_payable(api, invoice_id: str) -> dict:
    def leap(year):
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        if year % 4 == 0:
            return True
        return False

    def pad2(number):
        text = str(number)
        if len(text) == 1:
            return "0" + text
        return text

    def add_days(date_text, days):
        year = int(date_text[0:4])
        month = int(date_text[5:7])
        day = int(date_text[8:10])
        days = int(days)

        for step in range(days):
            day += 1
            if month in (4, 6, 9, 11):
                limit = 30
            elif month == 2:
                if leap(year):
                    limit = 29
                else:
                    limit = 28
            else:
                limit = 31

            if day > limit:
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1

        return str(year) + "-" + pad2(month) + "-" + pad2(day)

    def lower_text(value):
        return str(value).lower()

    def has_any_word(text, words):
        text = lower_text(text)
        for word in words:
            if word in text:
                return True
        return False

    def find_value(data, names):
        if isinstance(data, dict):
            for key in data:
                value = data[key]
                key_text = lower_text(key)
                for name in names:
                    if key_text == name:
                        return True, value
                found, nested = find_value(value, names)
                if found:
                    return True, nested
        elif isinstance(data, list):
            for item in data:
                found, nested = find_value(item, names)
                if found:
                    return True, nested
        return False, None

    def find_dict_section(data, words):
        if isinstance(data, dict):
            for key in data:
                value = data[key]
                if isinstance(value, dict) and has_any_word(key, words):
                    return True, value
            for key in data:
                found, nested = find_dict_section(data[key], words)
                if found:
                    return True, nested
        elif isinstance(data, list):
            for item in data:
                found, nested = find_dict_section(item, words)
                if found:
                    return True, nested
        return False, None

    def normalize_rate(value):
        rate = float(value)
        if rate >= 1:
            rate = rate / 100.0
        return rate

    def rounding_flags(data):
        whole = False
        down = False

        if isinstance(data, dict):
            for key in data:
                value = data[key]
                key_text = lower_text(key)

                if "whole" in key_text and "dollar" in key_text:
                    if isinstance(value, bool):
                        if value:
                            whole = True
                    elif isinstance(value, int):
                        if value != 0:
                            whole = True
                    elif isinstance(value, str):
                        value_text = lower_text(value)
                        if "whole" in value_text and "dollar" in value_text:
                            whole = True
                        if "down" in value_text or "floor" in value_text:
                            down = True

                if "unit" in key_text and isinstance(value, str):
                    value_text = lower_text(value)
                    if "whole" in value_text and "dollar" in value_text:
                        whole = True

                if "direction" in key_text and isinstance(value, str):
                    value_text = lower_text(value)
                    if "down" in value_text or "floor" in value_text:
                        down = True

                if "round" in key_text and isinstance(value, str):
                    value_text = lower_text(value)
                    if "whole" in value_text and "dollar" in value_text:
                        whole = True
                    if "down" in value_text or "floor" in value_text:
                        down = True

                if isinstance(value, str):
                    value_text = lower_text(value)
                    if "whole" in value_text and "dollar" in value_text:
                        whole = True
                    if "down" in value_text or "floor" in value_text:
                        if "round" in key_text or "direction" in key_text or "whole" in key_text or "dollar" in key_text:
                            down = True

                if isinstance(value, dict) or isinstance(value, list):
                    child_whole, child_down = rounding_flags(value)
                    if child_whole:
                        whole = True
                    if child_down:
                        down = True

        elif isinstance(data, list):
            for item in data:
                child_whole, child_down = rounding_flags(item)
                if child_whole:
                    whole = True
                if child_down:
                    down = True

        return whole, down

    invoice = api.read_invoice(invoice_id)
    po_number = invoice.get("po_number", invoice.get("purchase_order"))
    client_id = invoice.get("client_id", invoice.get("client"))
    invoice_date = invoice.get("invoice_date", invoice.get("date"))
    freight = invoice.get("freight_usd", invoice.get("freight", 0.0))
    invoice_terms = invoice.get("terms", invoice.get("payment_terms", {}))

    po = api.read_purchase_order(po_number)
    client_terms = api.read_client_terms(client_id)

    delivered_by_sku = {}
    for line in po["lines"]:
        sku = line["sku"]
        delivered = line["delivered"]
        delivered_by_sku[sku] = delivered_by_sku.get(sku, 0) + delivered

    goods_total = 0.0
    tax_base = 0.0
    retained_base = 0.0

    taxed_categories = client_terms.get("taxed_categories", [])
    taxed_category_set = set()
    for item in taxed_categories:
        taxed_category_set.add(lower_text(item))

    payment_rules = client_terms
    found, rules_section = find_dict_section(client_terms, ["payment_rules", "payment_rule"])
    if found and isinstance(rules_section, dict):
        payment_rules = rules_section

    retention_words = ["retention", "withhold", "retain", "holdback"]
    has_retention_name = False
    if isinstance(payment_rules, dict):
        for key in payment_rules:
            if has_any_word(key, retention_words):
                has_retention_name = True
                break

    found, retention_section = find_dict_section(payment_rules, retention_words)
    retention_rate_value = None
    retention_categories_value = None

    if found and isinstance(retention_section, dict):
        found_rate, retention_rate_value = find_value(
            retention_section,
            [
                "retention_rate",
                "retention_percent",
                "withholding_rate",
                "withholding_percent",
                "retain_rate",
                "retain_percent",
                "holdback_rate",
                "holdback_percent",
                "rate",
                "percent",
                "percentage",
            ],
        )
        if not found_rate:
            retention_rate_value = None

        found_categories, retention_categories_value = find_value(
            retention_section,
            [
                "retention_categories",
                "withholding_categories",
                "withheld_categories",
                "retain_categories",
                "holdback_categories",
                "categories",
                "category",
            ],
        )
        if not found_categories:
            retention_categories_value = None

    if retention_rate_value is None:
        found_rate, retention_rate_value = find_value(
            payment_rules,
            [
                "retention_rate",
                "retention_percent",
                "withholding_rate",
                "withholding_percent",
                "retain_rate",
                "retain_percent",
                "holdback_rate",
                "holdback_percent",
            ],
        )
        if not found_rate and has_retention_name:
            found_rate, retention_rate_value = find_value(
                payment_rules,
                ["rate", "percent", "percentage"],
            )
            if not found_rate:
                retention_rate_value = None

    if retention_categories_value is None:
        found_categories, retention_categories_value = find_value(
            payment_rules,
            [
                "retention_categories",
                "withholding_categories",
                "withheld_categories",
                "retain_categories",
                "holdback_categories",
            ],
        )
        if not found_categories and has_retention_name:
            found_categories, retention_categories_value = find_value(
                payment_rules,
                ["categories", "category"],
            )
            if not found_categories:
                retention_categories_value = None

    retention_rate = 0.0
    if retention_rate_value is not None:
        retention_rate = normalize_rate(retention_rate_value)

    retained_category_set = set()
    if isinstance(retention_categories_value, list):
        for item in retention_categories_value:
            retained_category_set.add(lower_text(item))
    elif retention_categories_value is not None:
        retained_category_set.add(lower_text(retention_categories_value))

    discount_percent = invoice_terms.get("discount_percent", invoice_terms.get("discount_rate", 0.0))
    discount_days = invoice_terms.get("discount_days", invoice_terms.get("early_payment_days", 0))
    net_days = invoice_terms.get("net_days", invoice_terms.get("payment_days", 0))

    for line in invoice["lines"]:
        sku = line["sku"]
        ordered_qty = line["quantity"]
        delivered_qty = delivered_by_sku.get(sku, 0)
        pay_qty = min(ordered_qty, delivered_qty)
        line_total = pay_qty * line["unit_price"]
        goods_total += line_total

        category = lower_text(line.get("category", ""))
        if category in taxed_category_set:
            tax_base += line_total
        if retained_category_set and category in retained_category_set:
            retained_base += line_total

    tax_rate = normalize_rate(client_terms.get("sales_tax_rate", 0.0))
    tax_amount = tax_base * tax_rate
    retention_amount = retained_base * retention_rate

    if discount_percent is None:
        discount_rate = 0.0
    else:
        discount_rate = normalize_rate(discount_percent)

    if discount_rate > 0:
        discount_amount = goods_total * discount_rate
        pay_on = add_days(invoice_date, discount_days)
    else:
        discount_amount = 0.0
        pay_on = add_days(invoice_date, net_days)

    amount = goods_total + tax_amount + freight - discount_amount - retention_amount
    amount = round(amount, 2)

    whole_dollar_down = False
    whole, down = rounding_flags(payment_rules)
    if whole and down:
        whole_dollar_down = True

    if whole_dollar_down:
        amount = float(int(amount))

    return {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}
