def amount_payable(api, invoice_id: str) -> dict:
    def leap(year):
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        if year % 4 == 0:
            return True
        return False

    def pad2(number):
        text = str(number)
        if len(text) == 1:
            return "0" + text
        return text

    def add_days(date_text, days):
        year = int(date_text[0:4])
        month = int(date_text[5:7])
        day = int(date_text[8:10])
        days = int(days)

        for step in range(days):
            day += 1
            if month in (4, 6, 9, 11):
                limit = 30
            elif month == 2:
                if leap(year):
                    limit = 29
                else:
                    limit = 28
            else:
                limit = 31

            if day > limit:
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1

        return str(year) + "-" + pad2(month) + "-" + pad2(day)

    def lower_text(value):
        return str(value).lower()

    def normalize_key(value):
        return lower_text(value).replace(" ", "_").replace("-", "_")

    def has_any_word(text, words):
        text = lower_text(text)
        for word in words:
            if word in text:
                return True
        return False

    def find_value(data, names):
        if isinstance(data, dict):
            for key in data:
                value = data[key]
                key_text = normalize_key(key)
                for name in names:
                    if key_text == name:
                        return True, value
                found, nested = find_value(value, names)
                if found:
                    return True, nested
        elif isinstance(data, list):
            for item in data:
                found, nested = find_value(item, names)
                if found:
                    return True, nested
        return False, None

    def find_section(data, names):
        if isinstance(data, dict):
            for key in data:
                value = data[key]
                key_text = normalize_key(key)
                for name in names:
                    if key_text == name:
                        return True, value
                found, nested = find_section(value, names)
                if found:
                    return True, nested
        elif isinstance(data, list):
            for item in data:
                found, nested = find_section(item, names)
                if found:
                    return True, nested
        return False, None

    def collect_text_items(data):
        items = []
        if isinstance(data, dict):
            for key in data:
                items.append(lower_text(key))
                items.extend(collect_text_items(data[key]))
        elif isinstance(data, list):
            for item in data:
                items.extend(collect_text_items(item))
        else:
            items.append(lower_text(data))
        return items

    def normalize_rate(value):
        if isinstance(value, bool):
            return None
        rate = float(value)
        if rate >= 1:
            rate = rate / 100.0
        return rate

    def parse_rate_text(text):
        text = lower_text(text)
        number = ""
        started = False
        for ch in text:
            if (ch >= "0" and ch <= "9") or ch == ".":
                number += ch
                started = True
            elif ch == "%" and started:
                break
            elif started:
                break
        if number:
            try:
                return normalize_rate(float(number))
            except Exception:
                return None
        return None

    def rate_value(value):
        if isinstance(value, bool):
            return None
        if isinstance(value, int) or isinstance(value, float):
            return normalize_rate(value)
        if isinstance(value, str):
            return parse_rate_text(value)
        return None

    def integer_value(value):
        if isinstance(value, bool):
            return 0
        if isinstance(value, int):
            return value
        if isinstance(value, float):
            return int(value)
        if isinstance(value, str):
            text = lower_text(value)
            number = ""
            started = False
            for ch in text:
                if ch >= "0" and ch <= "9":
                    number += ch
                    started = True
                elif started:
                    break
            if number:
                try:
                    return int(number)
                except Exception:
                    return 0
        return 0

    def text_matches(left, right):
        if left == right:
            return True
        if left in right or right in left:
            return True
        if len(left) > 1 and left.endswith("s") and left[:-1] == right:
            return True
        if len(right) > 1 and right.endswith("s") and right[:-1] == left:
            return True
        return False

    def any_match(text, options):
        for option in options:
            if text_matches(text, option):
                return True
        return False

    def is_candidate_text(text):
        if len(text) < 3:
            return False
        bad_words = [
            "rate",
            "percent",
            "percentage",
            "%",
            "payment",
            "term",
            "terms",
            "rule",
            "rules",
            "withhold",
            "withholding",
            "retain",
            "retention",
            "retainage",
            "holdback",
            "round",
            "whole",
            "down",
            "floor",
            "tax",
            "discount",
            "invoice",
            "order",
            "due",
        ]
        for word in bad_words:
            if word in text:
                return False
        return True

    invoice = api.read_invoice(invoice_id)
    po_number = invoice.get("po_number", invoice.get("purchase_order"))
    client_id = invoice.get("client_id", invoice.get("client"))
    invoice_date = invoice.get("invoice_date", invoice.get("date"))
    freight = invoice.get("freight_usd", invoice.get("freight", 0.0))
    invoice_terms = invoice.get("terms", invoice.get("payment_terms", {}))
    if not isinstance(invoice_terms, dict):
        invoice_terms = {}

    po = api.read_purchase_order(po_number)
    client_terms = api.read_client_terms(client_id)

    delivered_by_sku = {}
    for line in po["lines"]:
        sku = line["sku"]
        delivered = line["delivered"]
        delivered_by_sku[sku] = delivered_by_sku.get(sku, 0) + delivered

    taxed_categories = client_terms.get("taxed_categories", [])
    taxed_category_values = set()
    for text in collect_text_items(taxed_categories):
        if is_candidate_text(text):
            taxed_category_values.add(text)

    payment_rules = client_terms
    found, rules_section = find_section(client_terms, ["payment_rules", "payment_rule"])
    if found:
        payment_rules = rules_section

    retention_words = [
        "retention",
        "withhold",
        "withholding",
        "retain",
        "retainage",
        "holdback",
        "hold back",
    ]
    has_retention_name = False
    for text in collect_text_items(payment_rules):
        if has_any_word(text, retention_words):
            has_retention_name = True
            break

    found, retention_section = find_section(payment_rules, retention_words)
    if not found:
        found, retention_section = find_section(client_terms, retention_words)

    retention_rate_value = None
    retention_categories_value = None

    rate_names = [
        "retention_rate",
        "retention_percent",
        "retention_percentage",
        "withholding_rate",
        "withholding_percent",
        "withholding_percentage",
        "retain_rate",
        "retain_percent",
        "retainage_rate",
        "retainage_percent",
        "holdback_rate",
        "holdback_percent",
        "rate",
        "percent",
        "percentage",
    ]
    category_names = [
        "retention_categories",
        "withholding_categories",
        "withheld_categories",
        "retain_categories",
        "retainage_categories",
        "holdback_categories",
        "applies_to",
        "applies",
        "applies_on",
        "apply_to",
        "apply_on",
        "scope",
        "covered_categories",
        "category_names",
        "categories",
        "category",
        "material_categories",
        "line_categories",
        "work_categories",
        "item_categories",
        "materials",
    ]

    if found and isinstance(retention_section, dict):
        found_rate, retention_rate_value = find_value(retention_section, rate_names)
        if not found_rate:
            retention_rate_value = None

        found_categories, retention_categories_value = find_value(
            retention_section, category_names
        )
        if not found_categories:
            retention_categories_value = None

    if retention_rate_value is None:
        found_rate, retention_rate_value = find_value(payment_rules, rate_names)
        if not found_rate:
            found_rate, retention_rate_value = find_value(client_terms, rate_names)
            if not found_rate:
                retention_rate_value = None

    retention_rate = 0.0
    if retention_rate_value is not None:
        parsed_rate = rate_value(retention_rate_value)
        if parsed_rate is not None:
            retention_rate = parsed_rate
    if retention_rate == 0.0 and retention_section is not None:
        for text in collect_text_items(retention_section):
            parsed_rate = parse_rate_text(text)
            if parsed_rate is not None:
                retention_rate = parsed_rate
                break

    retention_category_values = set()
    if retention_categories_value is not None:
        for text in collect_text_items(retention_categories_value):
            if is_candidate_text(text):
                retention_category_values.add(text)

    if not retention_category_values and retention_section is not None:
        for text in collect_text_items(retention_section):
            if is_candidate_text(text):
                retention_category_values.add(text)

    discount_percent = invoice_terms.get("discount_percent", invoice_terms.get("discount_rate", 0.0))
    discount_days = integer_value(
        invoice_terms.get("discount_days", invoice_terms.get("early_payment_days", 0))
    )
    net_days = integer_value(invoice_terms.get("net_days", invoice_terms.get("payment_days", 0)))

    goods_total = 0.0
    tax_base = 0.0
    retained_base = 0.0

    for line in invoice["lines"]:
        sku = line["sku"]
        ordered_qty = line["quantity"]
        delivered_qty = delivered_by_sku.get(sku, 0)
        pay_qty = min(ordered_qty, delivered_qty)
        line_total = pay_qty * line["unit_price"]
        goods_total += line_total

        category = lower_text(line.get("category", ""))
        if taxed_category_values and any_match(category, taxed_category_values):
            tax_base += line_total
        if retention_rate > 0 and retention_category_values and any_match(category, retention_category_values):
            retained_base += line_total

    tax_rate = 0.0
    parsed_tax_rate = rate_value(client_terms.get("sales_tax_rate", 0.0))
    if parsed_tax_rate is not None:
        tax_rate = parsed_tax_rate
    tax_amount = tax_base * tax_rate
    retention_amount = retained_base * retention_rate

    discount_rate = 0.0
    parsed_discount_rate = rate_value(discount_percent)
    if parsed_discount_rate is not None:
        discount_rate = parsed_discount_rate

    if discount_rate > 0:
        discount_amount = goods_total * discount_rate
        pay_on = add_days(invoice_date, discount_days)
    else:
        discount_amount = 0.0
        pay_on = add_days(invoice_date, net_days)

    amount = goods_total + tax_amount + freight - discount_amount - retention_amount
    amount = round(amount, 2)

    whole_dollar_down = False
    whole, down = rounding_flags(payment_rules)
    if whole and down:
        whole_dollar_down = True

    if whole_dollar_down:
        amount = float(int(amount))

    return {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}

def rounding_flags(data):
    whole = False
    down = False
    items = collect_text_items(data)
    for text in items:
        if (
            "whole-dollar" in text
            or "whole dollar" in text
            or ("whole" in text and ("dollar" in text or "cent" in text))
            or "no cents" in text
            or "without cents" in text
        ):
            whole = True
        if "round down" in text or "down" in text or "floor" in text or "truncate" in text:
            down = True
    return whole, down
