    def normalize_text(value):
        text = str(value).lower()
        text = text.replace("_", " ")
        text = text.replace("-", " ")
        return text

    def as_float(value, default):
        try:
            return float(str(value).replace("%", ""))
        except Exception:
            return default

    def as_int(value, default):
        try:
            return int(float(str(value).replace("%", "")))
        except Exception:
            return default

    def fraction(value, default):
        number = as_float(value, default)
        if number is None:
            return default
        if number > 1:
            return number / 100.0
        return number

    def is_container(value):
        return isinstance(value, dict) or isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set)

    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
