    invoice_terms = invoice["terms"]

    retention_rules = []
    exclude_freight = False
    round_whole_down = False

    def scan_rules(value, in_retention=False, in_freight=False, in_round=False):
        nonlocal retention_rules, exclude_freight, round_whole_down

        if isinstance(value, dict):
            key_texts = []
            for key in value:
                key_texts.append(normalize_text(key))
            joined = " ".join(key_texts)

            current_retention = in_retention or ("retention" in joined or "withhold" in joined or "retainage" in joined)
            current_freight = in_freight or ("freight" in joined)
            current_round = in_round or ("round" in joined or ("whole" in joined and "dollar" in joined))

            if current_freight:
                for key, item in value.items():
                    key_text = normalize_text(key)
                    item_text = ""
                    if not is_container(item):
                        item_text = normalize_text(item)

                    if "freight" in key_text:
                        if "exclude" in key_text or "not" in key_text:
                            exclude_freight = True
                        if "include" in key_text and isinstance(item, bool) and not item:
                            exclude_freight = True
                        if "client" in key_text or "self" in key_text or "logistics" in key_text or "carrier" in key_text:
                            if not (isinstance(item, bool) and item is False):
                                exclude_freight = True
                        if isinstance(item, bool) and item and ("exclude" in key_text or "client" in key_text or "self" in key_text or "logistics" in key_text or "carrier" in key_text):
                            exclude_freight = True
                        if isinstance(item, str):
                            if "client" in item_text or "self" in item_text or "logistics" in item_text or "carrier" in item_text or "exclude" in item_text or "not" in item_text:
