                        round_whole_down = True

            if current_retention:
                categories = []
                percent = None

                for key, item in value.items():
                    key_text = normalize_text(key)
                    item_text = ""
                    if not is_container(item):
                        item_text = normalize_text(item)

                    if "category" in key_text or "class" in key_text or "sku" in key_text or "item" in key_text:
                        if isinstance(item, list) or isinstance(item, tuple) or isinstance(item, set):
