                        else:
                            category_text = normalize_text(item)
                            if len(category_text) > 0:
                                categories.append(category_text)

                    if "construction" in key_text and "material" in key_text:
                        categories.append("construction materials")
                    if "construction" in item_text and "material" in item_text:
                        categories.append("construction materials")

                    if "percent" in key_text or "pct" in key_text or "rate" in key_text or "withhold" in key_text or "retainage" in key_text or "retention" in key_text:
                        if isinstance(item, int) or isinstance(item, float):
                            percent = item
                        else:
                            maybe = as_float(item, None)
                            if maybe is not None:
                                percent = maybe
                    elif percent is None and (isinstance(item, int) or isinstance(item, float)):
                        if not ("category" in key_text or "class" in key_text or "sku" in key_text or "item" in key_text):
                            percent = item

                if len(categories) == 0 and ("construction" in joined and "material" in joined):
                    categories.append("construction materials")

                if percent is not None:
                    unique_categories = sorted(set(categories))
                    retention_rules.append((unique_categories, fraction(percent, 0.0)))

            for item in value.values():
                if is_container(item):
                    scan_rules(item, current_retention, current_freight, current_round)

        elif isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
            for item in value:
                scan_rules(item, in_retention, in_freight, in_round)

    scan_rules(client_terms)

    unique_rules = []
    seen_rules = set()
    for categories, rate in retention_rules:
        rule_key = (tuple(categories), rate)
        if rule_key not in seen_rules:
            seen_rules.add(rule_key)
            unique_rules.append((categories, rate))
    retention_rules = unique_rules

    delivered_by_sku = {}
