    def as_list(value):
        if value is None:
            return []
        if isinstance(value, list) or isinstance(value, tuple) or isinstance(value, set):
            return list(value)
        return [value]

    def lower_text(value):
        return str(value).lower()

    def truthy(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, int) or isinstance(value, float):
            return value != 0
        if value is None:
            return False
        text = lower_text(value).strip()
        return text not in ("", "0", "false", "no", "none", "off", "n", "null")

    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
    client_terms = api.read_client_terms(invoice["client_id"])

    invoice_terms = invoice.get("terms", invoice.get("vendor_payment_terms", {}))
    if not isinstance(invoice_terms, dict):
        invoice_terms = {}

    rules = client_terms.get("payment_rules", {})
    if not isinstance(rules, dict):
        rules = {}

    def get_rule(keys, default):
        for key in keys:
            if key in rules:
                return rules[key]
        for key in keys:
            if key in client_terms:
                return client_terms[key]
        return default

    invoice_date = invoice.get("invoice_date", invoice.get("date", ""))

    sales_tax_rate = get_rule(["sales_tax_rate", "tax_rate"], 0.0)
    if not isinstance(sales_tax_rate, float) and not isinstance(sales_tax_rate, int):
        try:
            sales_tax_rate = float(sales_tax_rate)
        except Exception:
            sales_tax_rate = 0.0
    if sales_tax_rate > 1:
        sales_tax_rate = sales_tax_rate / 100.0

    taxed_categories = as_list(get_rule(["taxed_categories", "taxable_categories"], []))
    taxed_set = set()
    for category in taxed_categories:
        taxed_set.add(lower_text(category))

    retention_rate = get_rule(
        ["retention_percent", "withholding_percent", "holdback_percent", "retain_percent",
         "retention_rate", "withholding_rate", "holdback_rate", "retain_rate"],
        0.0
    )
    if not isinstance(retention_rate, float) and not isinstance(retention_rate, int):
        try:
