    rounding_rule = get_rule(
        ["whole_dollars", "whole_dollar_payments", "round_to_whole_dollars",
         "round_payments_to_whole_dollars", "payment_rounding", "rounding"],
        None
    )
    if rounding_rule is not None:
        if isinstance(rounding_rule, str):
            rounding_text = lower_text(rounding_rule)
            if "whole" in rounding_text or "down" in rounding_text or "floor" in rounding_text:
                round_down_whole_dollars = True
        else:
            round_down_whole_dollars = truthy(rounding_rule)

    delivered_by_sku = {}
    for line in po["lines"]:
        sku = line["sku"]
        delivered = line["delivered"]
        delivered_by_sku[sku] = delivered_by_sku.get(sku, 0) + delivered

    goods_total = 0.0
    tax_base = 0.0
    retention_base = 0.0

    lines = invoice.get("lines", [])
    for line in lines:
        sku = line["sku"]
        ordered_qty = line["quantity"]
        delivered_qty = delivered_by_sku.get(sku, 0)
        pay_qty = min(ordered_qty, delivered_qty)
