    tax_amount = tax_base * sales_tax_rate
    freight = invoice.get("freight_usd", invoice.get("freight", 0.0))
    if not include_freight:
        freight = 0.0

    discount_percent = invoice_terms.get("discount_percent", 0.0)
    if not isinstance(discount_percent, float) and not isinstance(discount_percent, int):
        try:
            discount_percent = float(discount_percent)
        except Exception:
            discount_percent = 0.0
    if discount_percent > 1:
        discount_percent = discount_percent / 100.0

    discount_days = invoice_terms.get("discount_days", invoice_terms.get("net_days", 0))
    net_days = invoice_terms.get("net_days", discount_days)

    if discount_percent > 0:
        discount_amount = goods_total * discount_percent
        pay_on = add_days(invoice_date, discount_days)
    else:
        discount_amount = 0.0
        pay_on = add_days(invoice_date, net_days)

    retention_amount = retention_base * retention_rate + flat_retention

    amount = goods_total + tax_amount + freight - discount_amount - retention_amount
    if amount < 0:
        amount = 0.0

    if round_down_whole_dollars:
        amount = float(int(amount))
    else:
        amount = round(amount, 2)

    payment = {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}

    try:
        return api.schedule_payment(payment)
    except Exception:
        try:
            return api.schedule_payment(invoice_id=invoice_id, amount_usd=amount, pay_on=pay_on)
        except Exception:
            try:
                return api.schedule_payment(invoice_id, amount, pay_on)
            except Exception:
                return payment
