def amount_payable(api, invoice_id):
    def is_leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    def month_length(year, month):
        lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if month == 2 and is_leap(year):
            return 29
        return lengths[month - 1]

    def add_days(date_text, days):
        year = int(date_text[:4])
        month = int(date_text[5:7])
        day = int(date_text[8:10])

        while days > 0:
            remaining = month_length(year, month) - day
            if days <= remaining:
                day += days
                days = 0
            else:
                days -= remaining + 1
                day = 1
                month += 1
                if month > 12:
                    month = 1
                    year += 1

        year_text = str(year)
        month_text = str(month)
        day_text = str(day)
        if len(month_text) < 2:
            month_text = "0" + month_text
        if len(day_text) < 2:
            day_text = "0" + day_text
        return year_text + "-" + month_text + "-" + day_text

    invoice = api.read_invoice(invoice_id)
    purchase_order = api.read_purchase_order(invoice["po_number"])
    client_terms = api.read_client_terms(invoice["client_id"])

    delivered_by_sku = {}
    for line in purchase_order["lines"]:
        delivered_by_sku[line["sku"]] = line["delivered"]

    taxed_categories = set(client_terms["taxed_categories"])

    goods_subtotal = 0.0
    taxed_subtotal = 0.0

