        qty_payable = min(qty_invoiced, qty_delivered)
        line_amount = qty_payable * line["unit_price"]
        goods_subtotal += line_amount
        if line["category"] in taxed_categories:
            taxed_subtotal += line_amount

    freight = invoice["freight_usd"]
    tax_amount = round(taxed_subtotal * client_terms["sales_tax_rate"], 2)

    terms = invoice["terms"]
    discount_percent = terms.get("discount_percent", 0.0)
    discount_days = terms.get("discount_days", 0)

    if discount_percent and discount_days:
        discount_amount = round(goods_subtotal * discount_percent / 100.0, 2)
        amount_usd = round(goods_subtotal - discount_amount + tax_amount + freight, 2)
        pay_on = add_days(invoice["invoice_date"], discount_days)
    else:
        amount_usd = round(goods_subtotal + tax_amount + freight, 2)
        pay_on = add_days(invoice["invoice_date"], terms["net_days"])

    return api.schedule_payment(
        {
            "invoice_id": invoice_id,
            "amount_usd": amount_usd,
            "pay_on": pay_on,
        }
    )
