def amount_payable(api, invoice_id: str) -> dict:
    """Work out what to pay on an entered invoice, and when, under its client's accounts-payable terms."""

    def norm_text(value):
        if value is None:
            return ""
        return str(value).strip().lower().replace(" ", "_").replace("-", "_")

    def sku_text(value):
        if value is None:
            return ""
        return str(value).strip()

    def safe_float(value, default=0.0):
        if value is None:
            return default
        if isinstance(value, str):
            text = value.strip().replace(",", "").replace("$", "").replace("%", "")
            if text == "":
                return default
            try:
                return float(text)
            except Exception:
                return default
        try:
            return float(value)
        except Exception:
            return default

    def safe_int(value, default=0):
        if value is None:
            return default
        if isinstance(value, str):
            text = value.strip().replace(",", "").replace("$", "").replace("%", "")
            if text == "":
                return default
            try:
                return int(float(text))
            except Exception:
                return default
        try:
            return int(float(value))
        except Exception:
            return default

    def direct_lookup(obj, names):
        if not isinstance(obj, dict):
            return None
        wanted = set()
        for name in names:
            wanted.add(norm_text(name))
        for key in obj:
            if norm_text(key) in wanted:
                return obj[key]
        return None

    def recursive_lookup(obj, names):
        wanted = set()
        for name in names:
            wanted.add(norm_text(name))
        if isinstance(obj, dict):
            for key in obj:
                if norm_text(key) in wanted:
                    return obj[key]
            for value in obj.values():
                found = recursive_lookup(value, names)
                if found is not None:
                    return found
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                found = recursive_lookup(item, names)
                if found is not None:
                    return found
        return None

    def collect_dicts(obj):
        out = []
        if isinstance(obj, dict):
            out.append(obj)
            for value in obj.values():
                out.extend(collect_dicts(value))
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                out.extend(collect_dicts(item))
        return out

    def is_truthy(value):
        if isinstance(value, str):
            text = norm_text(value)
            return text in ("true", "yes", "y", "1", "all", "*")
        return bool(value)

    def month_days(year, month):
        if month in (1, 3, 5, 7, 8, 10, 12):
            return 31
        if month in (4, 6, 9, 11):
            return 30
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        if leap:
            return 29
        return 28

    def normalize_date(value):
        if value is None:
            return None
        text = str(value).strip()
        if "T" in text:
            text = text.split("T")[0]
        if " " in text:
            text = text.split(" ")[0]
        parts = text.split("-")
        if len(parts) != 3:
            return None
        try:
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])
        except Exception:
            return None
        if month < 1 or month > 12:
            return None
        md = month_days(year, month)
        if day < 1 or day > md:
            return None
        return str(year).zfill(4) + "-" + str(month).zfill(2) + "-" + str(day).zfill(2)

    def add_days(date_text, days):
        normalized = normalize_date(date_text)
        if normalized is None:
            return None
        parts = normalized.split("-")
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
        days = int(days)
        if days >= 0:
            day += days
            while True:
                md = month_days(year, month)
                if day <= md:
                    break
                day -= md
                month += 1
                if month > 12:
                    month = 1
                    year += 1
        else:
            day += days
            while day < 1:
                month -= 1
                if month < 1:
                    month = 12
                    year -= 1
                day += month_days(year, month)
        return str(year).zfill(4) + "-" + str(month).zfill(2) + "-" + str(day).zfill(2)

    def choose_base_total(rule, default_kind):
        basis = direct_lookup(rule, ["basis", "amount_basis", "discount_basis", "applies_to", "base"])
        basis_text = norm_text(basis)
        if basis_text == "":
            basis_text = default_kind
        total_base = goods_total + tax_total + freight_total
        if "invoice" in basis_text or "gross" in basis_text or "total" in basis_text or "all" in basis_text:
            return total_base
        if "subtotal" in basis_text or "net" in basis_text:
            return goods_total
        if "goods" in basis_text or "merch" in basis_text or "item" in basis_text or "product" in basis_text or "line" in basis_text:
            if "tax" in basis_text:
                return goods_total + tax_total
            return goods_total
        if "freight" in basis_text or "ship" in basis_text or "delivery" in basis_text:
            return freight_total
        if "tax" in basis_text:
            return tax_total
        if default_kind == "goods":
            return goods_total
        return total_base

    def rule_score(rule):
        score = 0
        if direct_lookup(rule, ["pay_on", "due_date", "due_on", "payment_date", "settlement_date", "date_due"]) is not None:
            score += 4
        if direct_lookup(rule, ["net_days", "due_days", "payment_days", "settlement_days", "term_days", "days", "pay_within_days"]) is not None:
            score += 3
        if direct_lookup(rule, ["amount_usd", "fixed_amount", "payment_amount", "due_amount", "amount_due"]) is not None:
            score += 3
        if direct_lookup(rule, ["pay_percent", "amount_percent", "percent_due", "settlement_percent", "payable_percent"]) is not None:
            score += 2
        if direct_lookup(rule, ["discount_percent", "cash_discount_percent", "early_payment_discount_percent", "prompt_payment_discount_percent"]) is not None:
            score += 2
        if direct_lookup(rule, ["discount_days", "cash_discount_days", "early_payment_discount_days", "discount_within_days"]) is not None:
            score += 1
        if direct_lookup(rule, ["holdback_percent", "retention_percent", "retainage_percent"]) is not None:
            score += 2
        return score

    def rule_date(rule, invoice_date):
        dates = []
        explicit_date = direct_lookup(rule, ["pay_on", "due_date", "due_on", "payment_date", "settlement_date", "date_due"])
        if explicit_date is not None:
            normalized = normalize_date(explicit_date)
            if normalized is not None:
                dates.append(normalized)

        discount_percent = direct_lookup(rule, ["discount_percent", "cash_discount_percent", "early_payment_discount_percent", "prompt_payment_discount_percent"])
        discount_days = direct_lookup(rule, ["discount_days", "cash_discount_days", "early_payment_discount_days", "discount_within_days"])
        if discount_percent is not None and discount_days is not None:
            dd = add_days(invoice_date, safe_int(discount_days, 0))
            if dd is not None:
                dates.append(dd)

        relative_days = direct_lookup(rule, ["net_days", "due_days", "payment_days", "settlement_days", "term_days", "days", "pay_within_days"])
        if relative_days is not None:
            rd = add_days(invoice_date, safe_int(relative_days, 0))
            if rd is not None:
                dates.append(rd)

        if len(dates) == 0:
            return None
        best = dates[0]
        for d in dates[1:]:
            if d < best:
                best = d
        return best

    def read_api(method_name, *args):
        try:
            if method_name == "read_invoice":
                return api.read_invoice(*args)
            if method_name == "read_purchase_order":
                return api.read_purchase_order(*args)
            if method_name == "read_client_terms":
                return api.read_client_terms(*args)
        except Exception as exc:
            raise ValueError("unable to call " + method_name + ": " + str(exc))
        raise ValueError("unsupported api method: " + method_name)

    invoice = read_api("read_invoice", invoice_id)

    po_number = recursive_lookup(invoice, ["po_number", "purchase_order", "purchase_order_number"])
    client_id = recursive_lookup(invoice, ["client_id", "client"])

    if po_number is None:
        raise ValueError("invoice is missing a purchase order number")
    if client_id is None:
        raise ValueError("invoice is missing a client id")

    po = read_api("read_purchase_order", po_number)
    terms = read_api("read_client_terms", client_id)

    po_client = recursive_lookup(po, ["client_id", "client"])
    if po_client is not None and po_client != client_id:
        raise ValueError("purchase order client does not match invoice client")

    po_by_sku = {}
    for line in po.get("lines", []):
        sku = sku_text(line.get("sku"))
        if sku == "":
            continue
        ordered_qty = line.get("quantity_ordered")
        if ordered_qty is None:
            ordered_qty = line.get("ordered_quantity")
        if ordered_qty is None:
            ordered_qty = line.get("quantity")
        delivered_qty = line.get("quantity_delivered")
        if delivered_qty is None:
            delivered_qty = line.get("delivered_quantity")
        if delivered_qty is None:
            delivered_qty = line.get("delivered")

        entry = po_by_sku.get(sku)
        if entry is None:
            entry = {"ordered": 0.0, "delivered": 0.0, "has_ordered": False, "has_delivered": False}

        if ordered_qty is not None:
            entry["ordered"] += safe_float(ordered_qty, 0.0)
            entry["has_ordered"] = True
        if delivered_qty is not None:
            entry["delivered"] += safe_float(delivered_qty, 0.0)
            entry["has_delivered"] = True

        po_by_sku[sku] = entry

    tax_rate_value = recursive_lookup(terms, ["sales_tax_rate", "tax_rate", "vat_rate", "gst_rate", "sales_tax"])
    tax_categories_value = recursive_lookup(terms, ["taxed_categories", "taxable_categories", "tax_categories", "categories_taxed"])
    tax_all_items = is_truthy(recursive_lookup(terms, ["tax_all", "tax_all_items", "all_taxed", "tax_everything"]))

    tax_rate_map = None
    default_tax_rate = 0.0
    if isinstance(tax_rate_value, dict):
        tax_rate_map = {}
        for key in tax_rate_value:
            tax_rate_map[norm_text(key)] = safe_float(tax_rate_value[key], 0.0)
        if "default" in tax_rate_map:
            default_tax_rate = tax_rate_map["default"]
    else:
        default_tax_rate = safe_float(tax_rate_value, 0.0)

    taxed_categories = set()
    if isinstance(tax_categories_value, dict):
        for key in tax_categories_value:
            if is_truthy(tax_categories_value[key]):
                taxed_categories.add(norm_text(key))
    elif isinstance(tax_categories_value, list) or isinstance(tax_categories_value, tuple):
        for category in tax_categories_value:
            taxed_categories.add(norm_text(category))
    elif tax_categories_value is not None:
        taxed_categories.add(norm_text(tax_categories_value))

    goods_total = 0.0
    taxed_goods_total = 0.0

    for line in invoice.get("lines", []):
        sku = sku_text(line.get("sku"))
        invoice_qty = line.get("quantity")
        if invoice_qty is None:
            invoice_qty = line.get("qty")
        if invoice_qty is None:
            invoice_qty = 0.0
        invoice_qty = safe_float(invoice_qty, 0.0)

        po_entry = po_by_sku.get(sku)
        quantities = [invoice_qty]
        if po_entry is not None:
            if po_entry.get("has_ordered"):
                quantities.append(po_entry.get("ordered", 0.0))
            if po_entry.get("has_delivered"):
                quantities.append(po_entry.get("delivered", 0.0))
        payable_qty = min(quantities) if len(quantities) > 0 else 0.0

        unit_price = line.get("unit_price")
        if unit_price is None:
            unit_price = line.get("unit_price_usd")
        unit_price = safe_float(unit_price, 0.0)

        line_total = payable_qty * unit_price
        goods_total += line_total

        category = norm_text(line.get("category"))
        line_tax_rate = 0.0
        taxable = tax_all_items or category in taxed_categories
        if tax_rate_map is not None:
            if category in tax_rate_map:
                line_tax_rate = tax_rate_map[category]
                taxable = True
            elif tax_all_items or category in taxed_categories:
                if "default" in tax_rate_map:
                    line_tax_rate = tax_rate_map["default"]
                else:
                    line_tax_rate = default_tax_rate
        else:
            if taxable:
                line_tax_rate = default_tax_rate

        if taxable:
            taxed_goods_total += line_total * line_tax_rate

    freight_total = recursive_lookup(invoice, ["freight_usd", "freight", "shipping_usd", "shipping", "delivery_usd"])
    freight_total = safe_float(freight_total, 0.0)

    freight_category = "freight"
    freight_tax_rate = 0.0
    if tax_rate_map is not None:
