    def norm_text(value):
        if value is None:
            return ""
        return str(value).strip().lower().replace(" ", "_").replace("-", "_")

    def sku_text(value):
        if value is None:
            return ""
        return str(value).strip()

    def normalize_date(value):
        if value is None:
            return None
        text = str(value).strip()
        if "T" in text:
            text = text.split("T")[0]
        if " " in text:
            text = text.split(" ")[0]
        parts = text.split("-")
        if len(parts) != 3:
            return None
        try:
            year = int(parts[0])
            month = int(parts[1])
            day = int(parts[2])
        except Exception:
            return None
        if month < 1 or month > 12:
            return None
        days_in_month = month_days(year, month)
        if day < 1 or day > days_in_month:
            return None
        return str(year).zfill(4) + "-" + str(month).zfill(2) + "-" + str(day).zfill(2)

    def month_days(year, month):
        if month in (1, 3, 5, 7, 8, 10, 12):
            return 31
        if month in (4, 6, 9, 11):
            return 30
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        if leap:
            return 29
        return 28

    def safe_float(value, default=0.0):
        if value is None:
            return default
        if isinstance(value, str):
            text = value.strip().replace(",", "").replace("$", "").replace("%", "")
            if text == "":
                return default
            try:
                return float(text)
            except Exception:
                if "/" in text or ":" in text:
                    return default
                out = ""
                dot = False
                sign = ""
                for ch in text:
                    if ch in "+-" and out == "" and sign == "":
                        sign = ch
                    elif ch.isdigit():
                        out += ch
                    elif ch == "." and not dot:
                        out += "."
                        dot = True
                if out == "" or out == ".":
                    return default
                if sign == "-":
                    out = "-" + out
                try:
                    return float(out)
                except Exception:
                    return default
        try:
            return float(value)
        except Exception:
            return default

    def safe_int(value, default=0):
        if value is None:
            return default
        if isinstance(value, str):
            text = value.strip().replace(",", "").replace("$", "").replace("%", "")
            if text == "":
                return default
            if normalize_date(text) is not None:
                return default
            try:
                return int(float(text))
            except Exception:
                if "/" in text or ":" in text:
                    return default
                out = ""
                sign = ""
                for ch in text:
                    if ch in "+-" and out == "" and sign == "":
                        sign = ch
                    elif ch.isdigit():
                        out += ch
                if out == "":
                    return default
                if sign == "-":
                    out = "-" + out
                try:
                    return int(float(out))
                except Exception:
                    return default
        try:
            return int(float(value))
        except Exception:
            return default

    def single_value(value):
        if isinstance(value, list) or isinstance(value, tuple):
            if len(value) == 1:
                return value[0]
        return value

    def direct_lookup(obj, names):
        if not isinstance(obj, dict):
            return None
        wanted = set()
        for name in names:
            wanted.add(norm_text(name))
        for key in obj:
            if norm_text(key) in wanted:
                return obj[key]
        return None

    def recursive_lookup(obj, names):
        wanted = set()
        for name in names:
            wanted.add(norm_text(name))
        if isinstance(obj, dict):
            for key in obj:
                if norm_text(key) in wanted:
                    return obj[key]
            for value in obj.values():
                found = recursive_lookup(value, names)
                if found is not None:
