            return None
        if isinstance(source, dict):
            if has_payment_fields(source):
                return source
            for name in ["payment_rules", "payment_terms", "payment_policy", "payment_schedule", "settlement_terms"]:
                child = direct_lookup(source, [name])
                if child is not None:
                    resolved = resolve_payment_rule(child)
                    if resolved is not None:
                        return resolved
            for name in ["rule", "rules", "schedule", "terms"]:
                child = direct_lookup(source, [name])
                if child is not None:
                    resolved = resolve_payment_rule(child)
                    if resolved is not None:
                        return resolved
            return None
        if isinstance(source, list) or isinstance(source, tuple):
            if len(source) == 1:
                return resolve_payment_rule(source[0])
            chosen = None
            for item in source:
                if isinstance(item, dict) and is_truthy(direct_lookup(item, ["default", "primary", "current", "active", "selected", "is_default"])):
                    if chosen is not None:
                        raise ValueError("ambiguous payment rules")
                    chosen = item
            if chosen is not None:
                return chosen
            raise ValueError("ambiguous payment rules")
        if has_payment_fields(source):
            return source
        return None

    def choose_base_total(rule, default_kind):
        basis = direct_lookup(rule, ["basis", "amount_basis", "discount_basis", "applies_to", "base"])
        basis_text = norm_text(basis)
        total_base = goods_total + tax_total + freight_total
        if basis_text == "":
            if default_kind == "goods":
                return goods_total
            return total_base
        if "invoice" in basis_text or "gross" in basis_text or "total" in basis_text or "all" in basis_text:
            return total_base
        if "subtotal" in basis_text or "net" in basis_text:
            return goods_total
        if ("goods" in basis_text or "merch" in basis_text or "item" in basis_text or
                "product" in basis_text or "line" in basis_text):
            if "tax" in basis_text:
                return goods_total + tax_total
            return goods_total
        if "freight" in basis_text or "ship" in basis_text or "delivery" in basis_text:
            return freight_total
        if "tax" in basis_text:
            return tax_total
        if default_kind == "goods":
            return goods_total
        return total_base

    invoice = read_api("read_invoice", invoice_id)

    po_number = direct_lookup(invoice, ["po_number", "purchase_order", "purchase_order_number"])
    client_id = direct_lookup(invoice, ["client_id", "client"])
    if po_number is None:
        raise ValueError("invoice is missing a purchase order number")
    if client_id is None:
        raise ValueError("invoice is missing a client id")

    po = read_api("read_purchase_order", po_number)
    terms = read_api("read_client_terms", client_id)

    po_client = direct_lookup(po, ["client_id", "client"])
    if po_client is not None and norm_text(po_client) != norm_text(client_id):
        raise ValueError("purchase order client does not match invoice client")

    po_by_sku = {}
    po_lines = line_items(direct_lookup(po, ["lines"]))
    for line in po_lines:
        if not isinstance(line, dict):
            continue
        sku = sku_text(direct_lookup(line, ["sku"]))
        if sku == "":
            continue
        ordered_qty = direct_lookup(line, ["quantity_ordered", "ordered_quantity", "quantity"])
        delivered_qty = direct_lookup(line, ["quantity_delivered", "delivered_quantity", "delivered"])

        entry = po_by_sku.get(sku)
        if entry is None:
            entry = {"ordered": 0.0, "delivered": 0.0, "has_ordered": False, "has_delivered": False}

        if ordered_qty is not None:
            entry["ordered"] += safe_float(ordered_qty, 0.0)
            entry["has_ordered"] = True
        if delivered_qty is not None:
            entry["delivered"] += safe_float(delivered_qty, 0.0)
            entry["has_delivered"] = True

        po_by_sku[sku] = entry

    tax_rate_value = direct_lookup(terms, ["sales_tax_rate", "tax_rate", "vat_rate", "gst_rate", "sales_tax"])
    tax_categories_value = direct_lookup(terms, ["taxed_categories", "taxable_categories", "tax_categories", "categories_taxed"])
    tax_all_items = is_truthy(direct_lookup(terms, ["tax_all", "tax_all_items", "all_taxed", "tax_everything"]))

    tax_rate_map = None
    default_tax_rate = 0.0
    if isinstance(tax_rate_value, dict):
        tax_rate_map = {}
        for key in tax_rate_value:
            tax_rate_map[norm_text(key)] = safe_float(tax_rate_value[key], 0.0)
        if "default" in tax_rate_map:
            default_tax_rate = tax_rate_map["default"]
    else:
        default_tax_rate = safe_float(tax_rate_value, 0.0)

    taxed_categories = set()
    if isinstance(tax_categories_value, dict):
        for key in tax_categories_value:
            if is_truthy(tax_categories_value[key]):
                taxed_categories.add(norm_text(key))
    elif isinstance(tax_categories_value, list) or isinstance(tax_categories_value, tuple):
        for category in tax_categories_value:
            taxed_categories.add(norm_text(category))
    elif tax_categories_value is not None:
        taxed_categories.add(norm_text(tax_categories_value))

    goods_total = 0.0
    taxed_goods_total = 0.0

    invoice_lines = line_items(direct_lookup(invoice, ["lines"]))
    for line in invoice_lines:
        if not isinstance(line, dict):
            continue

        sku = sku_text(direct_lookup(line, ["sku"]))
        invoice_qty = direct_lookup(line, ["quantity", "qty"])
        if invoice_qty is None:
            invoice_qty = 0.0
        invoice_qty = safe_float(invoice_qty, 0.0)

        po_entry = po_by_sku.get(sku)
        quantities = [invoice_qty]
        if po_entry is not None:
            if po_entry.get("has_ordered"):
                quantities.append(po_entry.get("ordered", 0.0))
            if po_entry.get("has_delivered"):
                quantities.append(po_entry.get("delivered", 0.0))
        payable_qty = min(quantities) if len(quantities) > 0 else 0.0

        unit_price = direct_lookup(line, ["unit_price", "unit_price_usd", "price", "rate"])
        unit_price = safe_float(unit_price, 0.0)

        line_total = payable_qty * unit_price
        goods_total += line_total

        category = norm_text(direct_lookup(line, ["category"]))
        taxable = tax_all_items or category in taxed_categories
        line_tax_rate = 0.0

        if tax_rate_map is not None:
            if category in tax_rate_map:
                line_tax_rate = tax_rate_map[category]
                taxable = True
            elif taxable:
                if "default" in tax_rate_map:
                    line_tax_rate = tax_rate_map["default"]
                else:
                    line_tax_rate = default_tax_rate
        else:
            if taxable:
                line_tax_rate = default_tax_rate

        if taxable:
            taxed_goods_total += line_total * line_tax_rate

    freight_total = direct_lookup(invoice, ["freight_usd", "freight", "shipping_usd", "shipping", "delivery_usd", "delivery"])
    freight_total = safe_float(freight_total, 0.0)

    freight_category = "freight"
    freight_taxable = tax_all_items or freight_category in taxed_categories or "shipping" in taxed_categories or "delivery" in taxed_categories
    freight_tax_rate = 0.0
    if tax_rate_map is not None:
        if freight_category in tax_rate_map:
            freight_tax_rate = tax_rate_map[freight_category]
        elif freight_taxable:
            if "default" in tax_rate_map:
                freight_tax_rate = tax_rate_map["default"]
            else:
                freight_tax_rate = default_tax_rate
    else:
        if freight_taxable:
            freight_tax_rate = default_tax_rate

    freight_tax_total = freight_total * freight_tax_rate
    tax_total = taxed_goods_total + freight_tax_total
    total_base = goods_total + tax_total + freight_total

    invoice_date = normalize_date(direct_lookup(invoice, ["invoice_date", "date", "document_date"]))
    if invoice_date is None:
        raise ValueError("invoice is missing a date")

    payment_rules_source = direct_lookup(
        terms,
        ["payment_rules", "payment_schedule", "payment_terms", "settlement_terms", "payment_policy", "schedule"]
    )
    payment_rule = resolve_payment_rule(payment_rules_source)
    if payment_rule is None and has_payment_fields(terms):
        payment_rule = terms
    if payment_rule is None:
        raise ValueError("client terms do not include a clear payment rule")

    pay_on = None

    if isinstance(payment_rule, dict):
        explicit_date = single_value(direct_lookup(payment_rule, ["pay_on", "due_date", "due_on", "payment_date", "settlement_date", "date_due"]))
        if explicit_date is not None:
            normalized = normalize_date(explicit_date)
            if normalized is not None:
                pay_on = normalized

        if pay_on is None:
            relative_days = single_value(direct_lookup(payment_rule, ["net_days", "due_days", "payment_days", "settlement_days", "term_days", "days", "pay_within_days"]))
            if relative_days is not None:
                pay_on = add_days(invoice_date, safe_int(relative_days, 0))

        discount_percent = single_value(direct_lookup(payment_rule, ["discount_percent", "cash_discount_percent", "early_payment_discount_percent", "prompt_payment_discount_percent"]))
        discount_days = single_value(direct_lookup(payment_rule, ["discount_days", "cash_discount_days", "early_payment_discount_days", "discount_within_days"]))

        if pay_on is None and discount_percent is not None and discount_days is not None:
            pay_on = add_days(invoice_date, safe_int(discount_days, 0))

        if pay_on is None:
            pay_on = invoice_date

        fixed_amount = single_value(direct_lookup(payment_rule, ["amount_usd", "fixed_amount", "payment_amount", "due_amount", "amount_due"]))
        pay_percent = single_value(direct_lookup(payment_rule, ["pay_percent", "amount_percent", "percent_due", "settlement_percent", "payable_percent"]))
        holdback_percent = single_value(direct_lookup(payment_rule, ["holdback_percent", "retention_percent", "retainage_percent"]))

        if fixed_amount is not None:
            amount = safe_float(fixed_amount, total_base)
        elif pay_percent is not None:
            base_total = choose_base_total(payment_rule, "total")
            amount = base_total * safe_float(pay_percent, 100.0) / 100.0
        elif holdback_percent is not None:
            base_total = choose_base_total(payment_rule, "total")
            amount = base_total * (1.0 - safe_float(holdback_percent, 0.0) / 100.0)
        elif discount_percent is not None and discount_days is not None:
            discount_deadline = add_days(invoice_date, safe_int(discount_days, 0))
            if discount_deadline is not None and pay_on is not None and pay_on <= discount_deadline:
                discount_base = choose_base_total(payment_rule, "goods")
                discount_base = min(discount_base, total_base)
                amount = discount_base * (1.0 - safe_float(discount_percent, 0.0) / 100.0) + (total_base - discount_base)
            else:
                amount = total_base
        else:
            amount = total_base

    else:
        simple_date = normalize_date(payment_rule)
        if simple_date is not None:
            pay_on = simple_date
            amount = total_base
        else:
            scalar_days = safe_int(payment_rule, None)
            if scalar_days is not None:
                pay_on = add_days(invoice_date, scalar_days)
                if pay_on is None:
                    pay_on = invoice_date
                amount = total_base
            else:
                pay_on = invoice_date
                amount = total_base

    amount = round(amount, 2)

    return {
        "invoice_id": invoice_id,
        "amount_usd": amount,
        "pay_on": pay_on
    }
