def amount_payable(api, invoice_id: str) -> dict:
    def isleap(year):
        if year % 400 == 0:
            return True
        if year % 100 == 0:
            return False
        return year % 4 == 0

    def adddays(date_text, delta):
        year = int(date_text[0:4])
        month = int(date_text[5:7])
        day = int(date_text[8:10])

        while delta > 0:
            if month == 2:
                limit = 29 if isleap(year) else 28
            elif month in (1, 3, 5, 7, 8, 10, 12):
                limit = 31
            else:
                limit = 30

            if day < limit:
                day = day + 1
            else:
                day = 1
                month = month + 1
                if month > 12:
                    month = 1
                    year = year + 1

            delta = delta - 1

        return str(year).zfill(4) + "-" + str(month).zfill(2) + "-" + str(day).zfill(2)

    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
    client = api.read_client_terms(invoice["client_id"])

    delivered = {}
    for line in po["lines"]:
        sku = line["sku"]
        if sku in delivered:
            delivered[sku] = delivered[sku] + line["delivered"]
        else:
            delivered[sku] = line["delivered"]

    taxed = set(client["taxed_categories"])
    goods_total = 0.0
    tax_base = 0.0

    for line in invoice["lines"]:
        sku = line["sku"]
        qty = line["quantity"]
        delivered_qty = delivered.get(sku, 0)
        pay_qty = min(qty, delivered_qty)
        line_total = round(pay_qty * line["unit_price"], 2)
        goods_total = round(goods_total + line_total, 2)
        if line["category"] in taxed:
            tax_base = round(tax_base + line_total, 2)

    freight = round(float(invoice.get("freight_usd", 0.0)), 2)
    tax = round(tax_base * float(client["sales_tax_rate"]), 2)

    terms = invoice["terms"]
    discount_percent = float(terms["discount_percent"])
    discount_days = int(terms["discount_days"])
    net_days = int(terms["net_days"])

    if discount_percent > 0:
        discount = round(goods_total * discount_percent / 100.0, 2)
        amount = round(goods_total - discount + tax + freight, 2)
        pay_on = adddays(invoice["invoice_date"], discount_days)
    else:
        amount = round(goods_total + tax + freight, 2)
        pay_on = adddays(invoice["invoice_date"], net_days)

    payload = {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}
    try:
        return api.schedule_payment(payload)
    except TypeError:
        return api.schedule_payment(invoice_id, amount, pay_on)
