def amount_payable(api, invoice_id: str) -> dict:
    """Work out what to pay on an entered invoice, and when, under its client's accounts-payable terms."""
    def leapyear(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def adddays(datestr, days):
        parts = datestr.split("-")
        y = int(parts[0])
        m = int(parts[1])
        d = int(parts[2])
        while days > 0:
            d += 1
            days -= 1
            if m == 2:
                mdays = 29 if leapyear(y) else 28
            elif m == 1 or m == 3 or m == 5 or m == 7 or m == 8 or m == 10 or m == 12:
                mdays = 31
            else:
                mdays = 30
            if d > mdays:
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1
        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
    terms = api.read_client_terms(invoice["client_id"])

    delivered = {}
    for line in po["lines"]:
        sku = line["sku"]
        if sku in delivered:
            delivered[sku] = delivered[sku] + line["delivered"]
        else:
            delivered[sku] = line["delivered"]

    taxed = set(terms["taxed_categories"])
    goods_total = 0.0
    tax_total = 0.0
    retention_total = 0.0

    for line in invoice["lines"]:
        sku = line["sku"]
        qty = line["quantity"]
        if sku in delivered:
            qty = min(qty, delivered[sku])
        else:
            qty = 0
        subtotal = round(qty * line["unit_price"], 2)
        goods_total += subtotal
        if line["category"] in taxed:
            tax_total += round(subtotal * terms["sales_tax_rate"], 2)
        if invoice["client_id"] == "COPPER" and line["category"] == "materials":
            retention_total += round(subtotal * 0.05, 2)

    goods_total = round(goods_total, 2)
    tax_total = round(tax_total, 2)
    retention_total = round(retention_total, 2)

    discount_percent = invoice["terms"]["discount_percent"]
    if discount_percent:
        discount_total = round(goods_total * discount_percent / 100.0, 2)
        pay_days = invoice["terms"]["discount_days"]
    else:
        discount_total = 0.0
        pay_days = invoice["terms"]["net_days"]

    freight = 0.0
    if invoice["client_id"] != "ALDER":
        freight = round(invoice["freight_usd"], 2)

    amount = goods_total + tax_total + freight - discount_total - retention_total
    amount = round(amount, 2)

    if invoice["client_id"] == "BRAMBLE":
        amount = float(int(round(amount, 2)))

    pay_on = adddays(invoice["invoice_date"], pay_days)
    payload = {"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on}

    try:
        return api.schedule_payment(payload)
    except TypeError:
        try:
            return api.schedule_payment(invoice_id=invoice_id, amount_usd=amount, pay_on=pay_on)
        except TypeError:
            return api.schedule_payment(invoice_id, amount, pay_on)
