def amount_payable(api, invoice_id):
    def leap_year(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def month_len(y, m):
        months = [31, 29 if leap_year(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return months[m - 1]

    def add_days(date_text, days):
        parts = date_text.split("-")
        y = int(parts[0])
        m = int(parts[1])
        d = int(parts[2])
        while days > 0:
            left = month_len(y, m) - d
            if days <= left:
                d += days
                days = 0
            else:
                days -= left + 1
                d = 1
                m += 1
                if m > 12:
                    m = 1
                    y += 1
        return str(y).zfill(4) + "-" + str(m).zfill(2) + "-" + str(d).zfill(2)

    invoice = api.read_invoice(invoice_id)
    po = api.read_purchase_order(invoice["po_number"])
    client = api.read_client_terms(invoice["client_id"])

    delivered = dict()
    for line in po["lines"]:
        delivered[line["sku"]] = line["delivered"]

    taxed = set(client["taxed_categories"])
    goods_total = 0.0
    tax_base = 0.0
    materials_total = 0.0

    for line in invoice["lines"]:
        sku = line["sku"]
        qty = line["quantity"]
        delivered_qty = min(qty, delivered.get(sku, 0))
        line_total = delivered_qty * line["unit_price"]
        goods_total += line_total
        if line["category"] in taxed:
            tax_base += line_total
        if invoice["client_id"] == "COPPER" and line["category"] == "materials":
            materials_total += line_total

    tax = round(tax_base * client["sales_tax_rate"], 2)

    freight = invoice["freight_usd"]
    if invoice["client_id"] == "ALDER":
        freight = 0.0

    discount_percent = client["discount_percent"] if "discount_percent" in client else invoice["terms"]["discount_percent"]
    discount_days = invoice["terms"]["discount_days"]
    net_days = invoice["terms"]["net_days"]

    if discount_percent > 0:
        pay_on = add_days(invoice["invoice_date"], discount_days)
        discount_amount = goods_total * discount_percent / 100.0
        discount_factor = 1.0 - discount_percent / 100.0
    else:
        pay_on = add_days(invoice["invoice_date"], net_days)
        discount_amount = 0.0
        discount_factor = 1.0

    amount = goods_total + tax + freight - discount_amount

    if invoice["client_id"] == "COPPER" and materials_total > 0:
        amount -= materials_total * discount_factor * 0.05

    if invoice["client_id"] == "BRAMBLE":
        amount = float(int(round(amount, 2)))
    else:
        amount = round(amount, 2)

    try:
        return api.schedule_payment(invoice_id=invoice_id, amount_usd=amount, pay_on=pay_on)
    except Exception:
        return api.schedule_payment({"invoice_id": invoice_id, "amount_usd": amount, "pay_on": pay_on})
