                        if low_tokens[j] == "at":
                            for k in range(j + 1, len(tokens)):
                                unit = parse_amount(bare(tokens[k]))
                                if unit is not None:
                                    break
                            break
                    if unit is not None:
                        total += qty * unit
                        found = True
                    break
        if found:
            return total
        return None

    def pipe_row_subtotal():
        total = 0.0
        found = False
        for line in text.split("\n"):
            low = line.lower()
            if "|" not in line:
                continue
            if ("subtotal" in low) or ("freight" in low) or ("delivery" in low) or ("carriage" in low) or ("amount due" in low) or ("total due" in low):
                continue
            tokens = token_list(line)
            nums = []
            for tok in tokens:
                v = parse_amount(bare(tok))
                if v is not None:
                    nums.append(v)
            if len(nums) >= 3:
                total += nums[-1]
                found = True
        if found:
            return total
        return None

    invoice_number = find_invoice_number()
    po_number = find_po_number()
    invoice_date = find_invoice_date()
    discount_percent, discount_days, net_days = parse_terms()

    subtotal_usd = explicit_subtotal()
    if subtotal_usd is None:
        subtotal_usd = pipe_row_subtotal()
    if subtotal_usd is None:
        subtotal_usd = item_clause_subtotal()
    if subtotal_usd is None:
        subtotal_usd = 0.0

    freight_usd = explicit_freight()
    if freight_usd is None:
        freight_usd = 0.0

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": round(float(subtotal_usd), 2),
        "freight_usd": round(float(freight_usd), 2),
        "discount_percent": float(round(discount_percent, 4)),
        "discount_days": int(discount_days),
        "net_days": int(net_days),
    }
