    else:
        text = str(data)

    def pad2(value):
        value = str(value)
        if len(value) == 1:
            return "0" + value
        return value

    def numbers(text):
        vals = []
        cur = ""
        for ch in text:
            if ch.isdigit():
                cur += ch
            else:
                if cur != "":
                    vals.append(cur)
                    cur = ""
        if cur != "":
            vals.append(cur)
        return vals

    def cleanmoney(text):
        out = ""
        for ch in text:
            if ch.isdigit() or ch == "." or ch == "," or ch == "-":
                out += ch
        return out.strip()

    def amount(text):
        text = cleanmoney(text.replace(" ", ""))
        if text == "" or text == "-" or text == "." or text == "-.":
            return 0.0
        lastdot = text.rfind(".")
        lastcom = text.rfind(",")
        if lastdot != -1 and lastcom != -1:
            if lastcom > lastdot:
                text = text.replace(".", "")
                text = text.replace(",", ".")
            else:
                text = text.replace(",", "")
        elif lastcom != -1:
            tail = text[lastcom + 1:]
            if len(tail) == 2:
                text = text.replace(".", "")
                text = text.replace(",", ".")
            else:
                text = text.replace(",", "")
        elif lastdot != -1:
            if text.count(".") > 1:
                parts = text.split(".")
                text = "".join(parts[:-1]) + "." + parts[-1]
        return float(text)

    def datevalue(text):
        text = text.strip()
        if "/" in text:
            parts = text.split("/")
            if len(parts) == 3:
                if len(parts[0]) == 4:
                    return parts[0] + "-" + pad2(parts[1]) + "-" + pad2(parts[2])
                if len(parts[2]) == 4:
                    return parts[2] + "-" + pad2(parts[0]) + "-" + pad2(parts[1])
        if "." in text:
            parts = text.split(".")
            if len(parts) == 3:
                if len(parts[0]) == 4:
                    return parts[0] + "-" + pad2(parts[1]) + "-" + pad2(parts[2])
                return parts[2] + "-" + pad2(parts[1]) + "-" + pad2(parts[0])
        if "-" in text:
            parts = text.split("-")
            if len(parts) == 3:
                if len(parts[0]) == 4:
                    return parts[0] + "-" + pad2(parts[1]) + "-" + pad2(parts[2])
                return parts[2] + "-" + pad2(parts[0]) + "-" + pad2(parts[1])
        return text

    def valueafter(line, label):
        low = line.lower()
        pos = low.find(label)
        if pos == -1:
            return ""
        piece = line[pos + len(label):]
        if ":" in piece:
            piece = piece.split(":", 1)[1]
        return piece.strip()

    lines = text.splitlines()

    invoice_number = ""
    po_number = ""
    invoice_date = ""
    subtotal_usd = 0.0
    freight_usd = 0.0
    discount_percent = 0
    discount_days = 0
    net_days = 0

    for line in lines:
        low = line.lower().strip()

        if invoice_number == "":
            if "invoice no" in low or "invoice number" in low or "invoice #" in low:
                val = ""
                if "invoice no" in low:
                    val = valueafter(line, "invoice no")
                elif "invoice number" in low:
                    val = valueafter(line, "invoice number")
                else:
                    val = valueafter(line, "invoice #")
                if val != "":
                    invoice_number = val

        if po_number == "":
            if "po number" in low:
                val = valueafter(line, "po number")
                if val != "":
                    po_number = val
            elif "purchase order" in low:
                val = valueafter(line, "purchase order")
                if val != "":
                    po_number = val
            elif low.startswith("po:") or low.startswith("po "):
                if ":" in line:
                    po_number = line.split(":", 1)[1].strip()
                else:
                    po_number = line[2:].strip()

        if invoice_date == "":
            if "invoice date" in low:
                val = valueafter(line, "invoice date")
                if val != "":
                    invoice_date = datevalue(val)

        if "terms" in low and ("net" in low or "/" in low):
            vals = numbers(line)
            if len(vals) >= 3:
                discount_percent = int(vals[0])
                discount_days = int(vals[1])
                net_days = int(vals[2])
            elif len(vals) == 2:
                discount_percent = int(vals[0])
                discount_days = int(vals[1])

        if "subtotal" in low:
            val = ""
            if ":" in line:
                val = line.split(":", 1)[1].strip()
            else:
                val = line[low.find("subtotal") + len("subtotal"):].strip()
            if val != "":
                subtotal_usd = amount(val)

        if "freight" in low or "shipping" in low:
            val = ""
            if ":" in line:
                val = line.split(":", 1)[1].strip()
            else:
                if "freight" in low:
                    val = line[low.find("freight") + len("freight"):].strip()
                else:
                    val = line[low.find("shipping") + len("shipping"):].strip()
            if val != "":
                freight_usd = amount(val)

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": subtotal_usd,
        "freight_usd": freight_usd,
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
