def parse_invoice(api, doc_id: str) -> dict:
    doc = api.read_document(doc_id)
    if isinstance(doc, dict):
        text = doc["text"]
    else:
        text = str(doc)

    lines = text.splitlines()

    month_map = {
        "jan": 1, "january": 1,
        "feb": 2, "february": 2,
        "mar": 3, "march": 3,
        "apr": 4, "april": 4,
        "may": 5,
        "jun": 6, "june": 6,
        "jul": 7, "july": 7,
        "aug": 8, "august": 8,
        "sep": 9, "sept": 9, "september": 9,
        "oct": 10, "october": 10,
        "nov": 11, "november": 11,
        "dec": 12, "december": 12,
    }

    def digits(text):
        out = ""
        for ch in text:
            if ch.isdigit():
                out += ch
        return out

    def to_number(text):
        s = text.strip()
        s = s.replace(",", "")
        s = s.replace("$", "")
        s = s.replace("€", "")
        s = s.replace("£", "")
        s = s.replace("¥", "")
        if s.endswith("%"):
            s = s[:-1]
        if s.startswith("(") and s.endswith(")"):
            s = "-" + s[1:-1]
        if s == "":
            return None
        if s[0] in "+-":
            sign = s[0]
            body = s[1:]
        else:
            sign = ""
            body = s
        if body == "":
            return None
        dot = 0
        for ch in body:
            if ch == ".":
                dot += 1
            elif not ch.isdigit():
                return None
        if dot > 1 or body == ".":
            return None
        return float(sign + body)

    def normalize_number(value):
        if value is None:
            return 0
        value = round(value, 2)
        if value == int(value):
            return int(value)
        return value

    def last_amount(segment):
        parts = segment.replace(",", "").replace("$", " ").replace("€", " ").replace("£", " ").replace("¥", " ").replace(":", " ").split()
        found = None
        for part in parts:
            num = to_number(part)
            if num is not None:
                found = num
        return found

    def parse_date_token(token):
        if token.count("-") == 2:
            pieces = token.split("-")
            if len(pieces) == 3:
                ok = True
                for piece in pieces:
                    if piece == "" or not piece.isdigit():
                        ok = False
                if ok:
                    return token
        return None

    def parse_date():
        for line in lines:
            parts = line.replace("|", " ").replace(",", " ").replace(":", " ").replace(".", " ").split()
            for i, part in enumerate(parts):
                key = part.lower()
                if key in month_map:
                    if i + 2 < len(parts):
                        day = digits(parts[i + 1])
                        year = digits(parts[i + 2])
                        if day != "" and year != "":
                            return year + "-" + str(month_map[key]).zfill(2) + "-" + str(int(day)).zfill(2)
                    if i >= 1 and i + 1 < len(parts):
                        day = digits(parts[i - 1])
                        year = digits(parts[i + 1])
                        if day != "" and year != "":
                            return year + "-" + str(month_map[key]).zfill(2) + "-" + str(int(day)).zfill(2)
            for part in parts:
                iso = parse_date_token(part)
                if iso is not None:
                    return iso
        return ""

    def parse_invoice_number():
        for line in lines:
            parts = line.replace("|", " ").replace(":", " ").replace(".", " ").replace(",", " ").replace("#", " # ").split()
            lowparts = [p.lower() for p in parts]
            for i, part in enumerate(lowparts):
                if part == "invoice":
                    for j in range(i + 1, len(parts)):
                        cand = parts[j].strip()
                        if cand == "":
                            continue
                        low = cand.lower()
                        if low in ["no", "number", "num", "#", "invoice"]:
                            continue
                        if any(ch.isdigit() for ch in cand) or "/" in cand or "-" in cand:
                            return cand
        return ""

    def parse_po_number():
        for line in lines:
            parts = line.replace("|", " ").replace(":", " ").replace(".", " ").replace(",", " ").replace("#", " # ").split()
            lowparts = [p.lower() for p in parts]
            for i, part in enumerate(lowparts):
                if part == "po":
                    for j in range(i + 1, len(parts)):
                        cand = parts[j].strip()
                        if cand == "":
                            continue
                        low = cand.lower()
                        if low in ["no", "number", "num", "#", "po"]:
                            continue
                        if any(ch.isdigit() for ch in cand) or "/" in cand or "-" in cand:
                            return cand
            for i in range(len(lowparts) - 1):
                if lowparts[i] == "purchase" and lowparts[i + 1] == "order":
                    for j in range(i + 2, len(parts)):
                        cand = parts[j].strip()
                        if cand == "":
                            continue
                        low = cand.lower()
                        if low in ["no", "number", "num", "#", "purchase", "order"]:
                            continue
                        if any(ch.isdigit() for ch in cand) or "/" in cand or "-" in cand:
                            return cand
        return ""

    def parse_terms():
        discount_percent = 0
        discount_days = 0
        net_days = 0
        for line in lines:
            low = line.lower()
            if "net" in low or "%" in line or "discount" in low:
                parts = line.replace(",", " ").replace("|", " ").replace(":", " ").replace(".", " ").split()
                for i, part in enumerate(parts):
                    lowpart = part.lower()
                    if lowpart == "net":
                        d = ""
                        if i + 1 < len(parts):
                            d = digits(parts[i + 1])
                        if d != "":
                            net_days = int(d)
                    elif lowpart.startswith("net") and lowpart != "net":
                        d = digits(part)
                        if d != "":
                            net_days = int(d)
                    if "/" in part:
                        seg = part.split("/")
                        if len(seg) >= 2:
                            p = to_number(seg[0])
                            d = digits(seg[1])
                            if p is not None and d != "":
                                discount_percent = p
                                discount_days = int(d)
                    if "%" in part:
                        p = to_number(part.replace("%", ""))
                        if p is not None:
                            discount_percent = p
                        if i + 1 < len(parts):
                            nxt = parts[i + 1].lower()
                            if nxt in ["day", "days"] and i + 2 < len(parts):
                                d = digits(parts[i + 2])
                                if d != "":
                                    discount_days = int(d)
                            else:
                                d = digits(parts[i + 1])
                                if d != "" and nxt != "net":
                                    discount_days = int(d)
        return normalize_number(discount_percent), discount_days, net_days

    subtotal = None
    freight = None
    for line in lines:
        segments = line.split("|")
        for seg in segments:
            low = seg.lower()
            if subtotal is None and ("goods total" in low or "subtotal" in low or "merchandise total" in low or ("goods" in low and "total" in low)):
                val = last_amount(seg)
                if val is not None:
                    subtotal = val
            if freight is None and ("delivery charge" in low or "freight" in low or "shipping" in low or "postage" in low):
                val = last_amount(seg)
                if val is not None:
                    freight = val

    if subtotal is None:
        total = 0
        count = 0
        for line in lines:
            low = line.lower()
            if line.strip().startswith("|") and "line total" not in low and "unit price" not in low and "description" not in low:
                val = last_amount(line)
                if val is not None:
                    total += val
                    count += 1
        if count > 0:
            subtotal = total

    invoice_number = parse_invoice_number()
    po_number = parse_po_number()
    invoice_date = parse_date()
    discount_percent, discount_days, net_days = parse_terms()

    if subtotal is None:
        subtotal = 0
    if freight is None:
        freight = 0

    subtotal = normalize_number(subtotal)
    freight = normalize_number(freight)

    return {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": subtotal,
        "freight_usd": freight,
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
