def parse_invoice(api, doc_id: str) -> dict:
    doc = api.read_document(doc_id)
    if isinstance(doc, dict):
        text = doc.get("text", "")
    else:
        text = doc

    def clean(word):
        return word.strip(" \t\r\n.,:;()[]{}<>\"'")

    def parse_amount(text_piece):
        piece = text_piece.replace(",", "")
        i = 0
        while i < len(piece) and not (piece[i].isdigit() or piece[i] == "."):
            i += 1
        num = ""
        while i < len(piece) and (piece[i].isdigit() or piece[i] == "."):
            num += piece[i]
            i += 1
        if num == "":
            return 0.0
        return float(num)

    def parse_last_number(text_piece):
        i = len(text_piece) - 1
        while i >= 0 and not (text_piece[i].isdigit() or text_piece[i] == "."):
            i -= 1
        num = ""
        while i >= 0 and (text_piece[i].isdigit() or text_piece[i] == "."):
            num = text_piece[i] + num
            i -= 1
        if num == "":
            return 0.0
        return float(num)

    def parse_first_int(text_piece):
        i = 0
        while i < len(text_piece):
            if text_piece[i].isdigit():
                num = ""
                while i < len(text_piece) and text_piece[i].isdigit():
                    num += text_piece[i]
                    i += 1
                if num != "":
                    return int(num)
            i += 1
        return 0

    def parse_quantity(text_piece):
        words = text_piece.replace(",", " ").split()
        for i in range(len(words) - 1, 0, -1):
            if clean(words[i]).lower() == "x":
                prev = clean(words[i - 1])
                if prev.isdigit():
                    return int(prev)
        return 0

    def parse_date(lines):
        months = {
            "january": "01",
            "february": "02",
            "march": "03",
            "april": "04",
            "may": "05",
            "june": "06",
            "july": "07",
            "august": "08",
            "september": "09",
            "october": "10",
            "november": "11",
            "december": "12",
        }
        for line in lines:
            parts = line.replace(",", " ").split()
            for i in range(len(parts)):
                m = clean(parts[i]).lower()
                if m in months:
                    day = ""
                    year = ""
                    if i > 0:
                        day = clean(parts[i - 1]).lower()
                        if day.endswith("st") or day.endswith("nd") or day.endswith("rd") or day.endswith("th"):
                            day = day[:-2]
                    if i + 1 < len(parts):
                        year = clean(parts[i + 1])
                    if day.isdigit() and year.isdigit():
                        return year + "-" + months[m] + "-" + day.zfill(2)
        for line in lines:
            parts = line.replace(",", " ").split()
            for part in parts:
                p = clean(part)
                if "/" in p or "-" in p:
                    sep = "/" if "/" in p else "-"
                    segs = p.split(sep)
                    if len(segs) == 3 and segs[0].isdigit() and segs[1].isdigit() and segs[2].isdigit():
                        a = segs[0]
                        b = segs[1]
                        c = segs[2]
                        if len(a) == 4:
                            return a + "-" + b.zfill(2) + "-" + c.zfill(2)
                        if len(c) == 4:
                            if int(a) > 12:
                                return c + "-" + b.zfill(2) + "-" + a.zfill(2)
                            return c + "-" + a.zfill(2) + "-" + b.zfill(2)
        return ""

    lines = [line.strip() for line in text.split("\n")]
    words = text.replace("\n", " ").split()

    invoice_number = ""
    for line in lines:
        low = line.lower()
        keywords = ["invoice number", "invoice no", "invoice #", "invoice"]
        for keyword in keywords:
            pos = low.find(keyword)
            if pos != -1:
                rest = line[pos + len(keyword):].strip(" \t\r\n:,-")
                parts = rest.split()
                for part in parts:
                    c = clean(part)
                    cl = c.lower()
                    if cl in ["number", "no", "num", "#"]:
                        continue
                    if c != "":
                        invoice_number = c
                        break
                if invoice_number != "":
                    break
        if invoice_number != "":
            break

    po_number = ""
    for word in words:
        c = clean(word)
        up = c.upper()
        if up.startswith("PO-") or up.startswith("PO/"):
            po_number = c
            break
        if up.startswith("PO") and len(up) > 2:
            has_digit = False
            for ch in up:
                if ch.isdigit():
                    has_digit = True
                    break
            if has_digit:
                po_number = c
                break
    if po_number == "":
        for line in lines:
            low = line.lower()
            pos = low.find("po")
            if pos != -1:
                rest = line[pos + 2:].strip(" \t\r\n:,-")
                parts = rest.split()
                if len(parts) > 0:
                    po_number = clean(parts[0])
                    if po_number != "":
                        break

    invoice_date = parse_date(lines)

    subtotal = 0.0
    for piece in text.split(";"):
        low_piece = piece.lower()
        if " at $" in low_piece and "each" in low_piece:
            left, right = piece.split(" at $", 1)
            qty = parse_quantity(left)
            price = parse_amount(right)
            subtotal += qty * price
    subtotal = round(subtotal, 2)

    freight_usd = 0.0
    for line in lines:
        low = line.lower()
        if "freight" in low or "carriage" in low or "shipping" in low or "postage" in low or "delivery" in low:
            freight_usd = round(parse_amount(line), 2)
            if freight_usd != 0.0:
                break

    discount_percent = 0.0
    discount_days = 0
    net_days = 0

    for line in lines:
        low = line.lower()
        if "%" in line:
            pos = line.find("%")
            discount_percent = round(parse_last_number(line[:pos]), 2)
            if "within" in low:
                pos2 = low.rfind("within")
                discount_days = parse_first_int(line[pos2 + len("within"):])
        if ("settle" in low or "net" in low or "terms" in low or "pay within" in low) and "days" in low:
            if net_days == 0:
                net_days = parse_first_int(line)

    result = {
        "doc_id": doc_id,
        "invoice_number": invoice_number,
        "po_number": po_number,
        "invoice_date": invoice_date,
        "subtotal_usd": subtotal,
        "freight_usd": freight_usd,
        "discount_percent": discount_percent,
        "discount_days": discount_days,
        "net_days": net_days,
    }
    return result
