        if pos >= 0:
            rest = line[pos + len(label):].strip()
            if rest.startswith(':') or rest.startswith('-') or rest.startswith('='):
                rest = rest[1:].strip()
            return rest
        return ''

    def parse_date(text):
        nums = collect_ints(text)
        year = 0
        month = 0
        day = 0
        if len(nums) >= 3:
            if nums[0] >= 1000:
                year = nums[0]
                month = nums[1]
                day = nums[2]
            elif nums[2] >= 1000:
                a = nums[0]
                b = nums[1]
                year = nums[2]
                if a > 12 and b <= 12:
                    day = a
                    month = b
                elif b > 12 and a <= 12:
                    day = b
                    month = a
                else:
                    day = a
                    month = b
            else:
