def parse_invoice(api, doc_id: str) -> dict:
    response = api.read_document(doc_id)
    if isinstance(response, dict):
        text = response.get("text", "")
    else:
        text = str(response)

    lines = []
    for line in text.splitlines():
        s = line.strip()
        if s:
            lines.append(s)

    def getvalue(line, keys):
        low = line.lower()
        for key in keys:
            pos = low.find(key)
            if pos != -1:
                val = line[pos + len(key):]
                val = val.lstrip(" \t:;,-#")
                return val.strip()
        if ":" in line:
            return line.split(":", 1)[1].strip()
        return ""

    def digitsparts(s):
        parts = []
        token = ""
        for ch in s:
            if ch.isdigit():
                token += ch
            else:
                if token:
                    parts.append(token)
                    token = ""
        if token:
            parts.append(token)
        return parts

    def parsedate(s):
        parts = digitsparts(s)
        if len(parts) < 3:
            return ""
        a = parts[0]
        b = parts[1]
        c = parts[2]
        if len(a) == 4:
            y = a
            m = b
            d = c
        elif len(c) == 4:
            ai = int(a)
            bi = int(b)
            if ai > 12 and bi <= 12:
                d = a
                m = b
                y = c
            elif bi > 12 and ai <= 12:
                m = a
                d = b
                y = c
            else:
                d = a
                m = b
                y = c
        else:
            return ""
        return y.zfill(4) + "-" + m.zfill(2) + "-" + d.zfill(2)

    def numtokens(s):
        parts = []
        token = ""
        for ch in s:
            if ch.isdigit() or ch in ".,-":
                token += ch
            else:
                if token:
                    parts.append(token)
                    token = ""
        if token:
            parts.append(token)
        return parts

    def cleanmoney(s):
        t = ""
        has = False
        for ch in s:
            if ch.isdigit():
                t += ch
                has = True
            elif ch in ".,-":
                t += ch
        if not has:
            return 0.0
        t = t.replace("-", "")
        if "." in t and "," in t:
            if t.rfind(".") > t.rfind(","):
                t = t.replace(",", "")
            else:
                t = t.replace(".", "").replace(",", ".")
        elif "," in t:
            t = t.replace(",", ".")
        if t == "":
            return 0.0
        return float(t)

    def whole(v):
        if abs(v - int(v)) < 1e-9:
            return int(v)
        return v

    invoice = ""
    po = ""
    date = ""
    subtotal = 0.0
    freight = 0.0
    discount = 0.0
    discdays = 0
    netdays = 0

    for line in lines:
        low = line.lower()

        if invoice == "" and (
            "invoice no" in low or
            "invoice number" in low or
            "invoice #" in low or
            "inv no" in low or
            "inv #" in low or
            "inv. no" in low or
            "invoice no." in low
        ):
            invoice = getvalue(line, [
                "invoice no",
                "invoice number",
                "invoice #",
                "inv no",
                "inv #",
                "inv. no",
                "invoice no."
            ])
            if invoice == "":
                invoice = line.strip()

        if po == "" and (
            "po number" in low or
            "po no" in low or
            "po #" in low or
            "purchase order" in low or
            "p.o. no" in low or
            "p.o. number" in low
        ):
            po = getvalue(line, [
                "po number",
                "po no",
                "po #",
                "purchase order",
                "p.o. no",
                "p.o. number"
            ])
            if po == "":
                po = line.strip()

        if date == "" and (
            "invoice date" in low or
            (low.startswith("date") and "due" not in low) or
            "inv date" in low or
            "inv. date" in low
        ):
            date = parsedate(getvalue(line, ["invoice date", "inv date", "inv. date", "date"]) or line)

        if subtotal == 0.0 and ("subtotal" in low or "sub total" in low):
            subtotal = round(cleanmoney(getvalue(line, ["subtotal", "sub total"]) or line), 2)

        if freight == 0.0 and ("freight" in low or "shipping" in low or "delivery" in low):
            freight = round(cleanmoney(getvalue(line, ["freight", "shipping", "delivery"]) or line), 2)

        if discount == 0.0 and discdays == 0 and netdays == 0 and (
            "terms" in low or ("net" in low and any(ch.isdigit() for ch in line))
        ):
            segment = getvalue(line, ["terms"])
            if segment == "":
                segment = line
            nums = numtokens(segment)
            vals = []
            for n in nums:
                vals.append(cleanmoney(n))
            if len(vals) >= 3:
                discount = vals[0]
                discdays = int(round(vals[1]))
                netdays = int(round(vals[2]))
            elif len(vals) == 2:
                discount = vals[0]
                discdays = int(round(vals[1]))
            elif len(vals) == 1:
                netdays = int(round(vals[0]))
            discount = whole(discount)

    return {
        "doc_id": doc_id,
        "invoice_number": invoice,
        "po_number": po,
        "invoice_date": date,
        "subtotal_usd": subtotal,
        "freight_usd": freight,
        "discount_percent": discount,
        "discount_days": discdays,
        "net_days": netdays,
    }
