            while True:
                p = low.find(stop, p)
                if p == -1:
                    break
                beforeok = p == 0 or not low[p - 1].isalnum()
                after = p + len(stop)
                afterok = after == len(low) or not low[after].isalnum()
                if beforeok and afterok and p < pos:
